   741→ * Research Foundation:
   742→ * - Edelman (2024): Recovery via education, demonstrated benefits, visible impact
   743→ * - Frontiers Psychology (2024): +49% output quality, +52% privacy with feedback loops
   744→ * - DORA (2024): Continuous feedback critical for sustained trust
   745→ *
   746→ * Key Insight: Trust can recover if AI systems demonstrate benefits, safety, and explainability.
   747→ * This enables escape from dystopia traps and path-dependent recovery.
   748→ */
   749→export function updateTrustRecovery(state: GameState): void {
   750→  let trustChange = 0;
   751→
   752→  // === RECOVERY FACTORS ===
   753→
   754→  // 1. Education campaigns (+1%/month)
   755→  if (state.policies?.aiEducationCampaigns?.active) {
   756→    trustChange += TRUST_RECOVERY_FROM_EDUCATION;
   757→  }
   758→
   759→  // 2. Demonstrated benefits (+2%/month when QoL improving)
   760→  const qolTrend = state.globalMetrics.qualityOfLife - (state.globalMetrics.previousQoL || 0.5);
   761→  if (qolTrend > 0) {
   762→    trustChange += TRUST_RECOVERY_FROM_DEMONSTRATED_BENEFITS;
   763→  }
   764→  // Store for next comparison
   765→  state.globalMetrics.previousQoL = state.globalMetrics.qualityOfLife;
   766→
   767→  // 3. Safety record (+1.5%/month with no incidents for 6+ months)
   768→  const recentIncidents = (state.significantEvents || []).filter(
   769→    event => (event.type === 'AISafetyIncident' || event.type === 'AIAlignment') &&
   770→             state.currentMonth - (event.month || 0) < 6
   771→  ).length;
   772→
   773→  if (recentIncidents === 0) {
