      qualityOfLife: [],
      outcomeProbs: [],
      controlCapability: [],
      metrics: []
    }
  };

  // Phase 2: Initialize and link organizations
  state.organizations = initializeOrganizations();
  linkDataCentersToOrganizations(state);
  linkAIModelsToOrganizations(state);

