   819→  if (state.society.segments && state.society.segments.length > 0) {
   820→    // Apply trust change to each segment with multipliers based on adaptability and openness
   821→    for (const seg of state.society.segments) {
   822→      // Recovery multiplier: Early adopters (high adaptability, high openness) recover faster
   823→      // Research: Rogers (2003) - innovators/early adopters forgive mistakes
   824→      const recoveryMultiplier = (seg.adaptability * 0.7 + seg.openness * 0.3);
