   827→      // Research: Bass diffusion model - laggards resist adoption, amplify concerns
   828→      const decayMultiplier = (1.0 - seg.adaptability * 0.5);
   829→
   830→      // Apply multipliers based on sign of change
   831→      let segmentTrustChange = baseTrustChange;
   832→      if (baseTrustChange > 0) {
   833→        // Recovery: Early adopters recover faster
   834→        segmentTrustChange *= recoveryMultiplier;
