   878→      state.society.trustInAI = calculateComprehensiveTrustInAI(state);
   879→    }
   880→    state.society.trustInAI = Math.max(0, Math.min(1, state.society.trustInAI + baseTrustChange));
   881→
   882→    // Log recovery/decay (only on significant changes)
   883→    if (Math.abs(baseTrustChange) > 0.02 && state.currentMonth % 6 === 0) {
   884→      console.log(`\n🔄 TRUST DYNAMICS (Month ${state.currentMonth}) - GLOBAL`);
   885→      console.log(`   Trust level: ${(state.society.trustInAI * 100).toFixed(1)}%`);
