/**
 * Calculate emergency response effectiveness
 * FIX #13: Adjusted timing penalty for multi-crisis scenarios
 *
 * Research Foundation:
 * - Ashraf (2020): Every 7.49-day delay doubles PANDEMIC mortality (r² = 0.64)
 * - BUT: Economic/social/technological crises don't spread exponentially like pandemics
 * - TARP (2008): 3-month delay, ~50% effective at preventing Depression
 * - Nordic COVID (2020): 2-month delayed responses still 60-70% effective
 *
 * Formula: effectiveness = 1.0 / (2^(delayMonths / 1.5))
 * - 0 delay: 100% effectiveness
 * - 1.5 months delay: 50% effectiveness (threshold for Tier 1 recovery bonuses)
 * - 3.0 months delay: 25% effectiveness (still meaningful)
 * - 6.0 months delay: 6.25% effectiveness (too late)
 *
 * ADJUSTMENT: Changed denominator from 0.25 (too harsh) → 1.5 (more realistic)
 * Reasoning: Ashraf's exponential timing is specific to pandemic spread dynamics,
 * not applicable to all crisis types. Government responses at 2-3 months still
 * provide meaningful mitigation for economic/social/technological crises.
 */
export function calculateEmergencyEffectiveness(
  crisisSeverity: number,
  responseDelayMonths: number,
  deploymentTime: number,
  coordinationQuality: number
): number {
  // Base effectiveness from timing (exponential penalty, ADJUSTED FOR MULTI-CRISIS)
  // FIX #13: More forgiving timing penalty (6× more forgiving than original)
  const timingEffectiveness = 1.0 / Math.pow(2, responseDelayMonths / 1.5);

  // Deployment speed matters - faster deployment = more effective
  // 0.5 month deployment = 1.0×, 3 month deployment = 0.5×
  const deploymentEffectiveness = 1.0 - (Math.min(3, deploymentTime) / 6);

  // Coordination quality directly impacts effectiveness
  // Research: FEMA coordination failures (Katrina) vs success (Sandy)
  const coordEffectiveness = 0.5 + (coordinationQuality * 0.5); // 50-100%

  // Crisis severity reduces effectiveness (harder to respond to severe crises)
  const severityPenalty = 1.0 - (crisisSeverity * 0.3); // Max 30% reduction

  // Combined effectiveness
  const effectiveness = timingEffectiveness * deploymentEffectiveness * coordEffectiveness * severityPenalty;

  return Math.max(0.01, Math.min(1.0, effectiveness));
}

