  // === CRITICAL INFRASTRUCTURE ===
  criticalNodes: CriticalInfrastructureNode[];
  nodesProtected: number;                // Count of hardened nodes
  cascadeRiskReduction: number;          // [0, 1] Reduction in cascade probability
}

