   383→export function updatePlanetaryBoundaries(state: GameState): void {
   384→  const system = state.planetaryBoundariesSystem;
   385→  if (!system) return;
   386→
   387→  const env = state.environmentalAccumulation;
   388→  const resources = state.resourceEconomy;
   389→
   390→  // === 1. UPDATE BOUNDARY VALUES ===
   391→
   392→  // Climate change (from environmental system)
   393→  const climateBoundary = system.boundaries.climate_change;
   394→  if (!climateBoundary) {
   395→    console.warn('⚠️  Planetary Boundaries: climate_change boundary not found');
   396→    return;
   397→  }
   398→  climateBoundary.currentValue = Math.max(0, 1.21 - (env.climateStability * 0.21));
   399→  updateBoundaryStatus(climateBoundary);
   400→
   401→  // Biosphere integrity (from biodiversity)
   402→  system.boundaries.biosphere_integrity.currentValue = Math.max(0, 10.0 * (1 - env.biodiversityIndex));
   403→  updateBoundaryStatus(system.boundaries.biosphere_integrity);
   404→
   405→  // Freshwater (from freshwater system if available)
   406→  // FIX #3 (Oct 18, 2025): Add AI infrastructure water consumption
   407→  // Research: UC Riverside (2024), RAND (2024) - AI data centers consume massive water
   408→  if (state.freshwaterSystem) {
   409→    const { calculateAIResourceConsumption, getWaterStressContribution } = require('./aiInfrastructureResources');
   410→    const aiWaterStress = getWaterStressContribution(state);
   411→    const baseStress = state.freshwaterSystem.waterStress;
   412→    const totalStress = baseStress + aiWaterStress;
   413→
   414→    system.boundaries.freshwater_change.currentValue = Math.max(0, 1.15 + (totalStress - 0.5) * 0.7);
   415→  }
   416→  updateBoundaryStatus(system.boundaries.freshwater_change);
   417→
   418→  // Biogeochemical flows (from phosphorus system if available)
   419→  if (state.phosphorusSystem) {
   420→    const depletion = 1 - (state.phosphorusSystem.globalReserves / 100);
   421→    system.boundaries.biogeochemical_flows.currentValue = Math.max(0, 2.94 + depletion * 0.5);
   422→  }
   423→  updateBoundaryStatus(system.boundaries.biogeochemical_flows);
   424→
   425→  // Novel entities (from environmental pollution)
   426→  system.boundaries.novel_entities.currentValue = Math.max(0, 1.5 + (env.pollutionLevel - 0.3) * 0.5);
   427→  updateBoundaryStatus(system.boundaries.novel_entities);
   428→
   429→  // Ocean acidification (from ocean system if available)
   430→  if (state.oceanAcidificationSystem) {
   431→    const aragonite = state.oceanAcidificationSystem.aragoniteSaturation;
   432→    system.boundaries.ocean_acidification.currentValue = Math.max(0, 1.05 + (0.8 - aragonite) * 1.25);
   433→  }
   434→  updateBoundaryStatus(system.boundaries.ocean_acidification);
   435→
   436→  // Ozone (improving steadily - Montreal Protocol success!)
   437→  system.boundaries.stratospheric_ozone.currentValue = Math.max(0, system.boundaries.stratospheric_ozone.currentValue - 0.0005);
   438→  updateBoundaryStatus(system.boundaries.stratospheric_ozone);
   439→
   440→  // Aerosols (improving with regulations)
   441→  system.boundaries.atmospheric_aerosols.currentValue = Math.max(0, system.boundaries.atmospheric_aerosols.currentValue - 0.0003);
   442→  updateBoundaryStatus(system.boundaries.atmospheric_aerosols);
   443→
   444→  // === 2. RECALCULATE AGGREGATE METRICS ===
   445→  system.boundariesBreached = Object.values(system.boundaries)
   446→    .filter(b => b.status !== 'safe').length;
   447→
   448→  system.boundariesWorsening = Object.values(system.boundaries)
   449→    .filter(b => b.trend === 'worsening').length;
   450→
   451→  system.boundariesImproving = Object.values(system.boundaries)
   452→    .filter(b => b.trend === 'improving').length;
   453→
   454→  system.coreBoundariesBreached =
   455→    system.boundaries.climate_change.status !== 'safe' &&
   456→    system.boundaries.biosphere_integrity.status !== 'safe';
   457→
   458→  // === 3. CALCULATE TIPPING POINT RISK ===
   459→  system.tippingPointRisk = calculateTippingPointRisk(
   460→    system.boundariesBreached,
   461→    system.boundariesWorsening,
   462→    system.coreBoundariesBreached,
   463→    system.boundaries
   464→  );
   465→
   466→  // Track history
   467→  system.boundariesBreachedHistory.push(system.boundariesBreached);
   468→  system.tippingPointRiskHistory.push(system.tippingPointRisk);
   469→
   470→  // === 4. BAYESIAN CASCADE TRIGGER (Oct 16, 2025) ===
   471→  // Blended model with 3 elements:
   472→  // 1. Time-dependent hazard functions (different threats kill at different speeds)
   473→  // 2. Survival-based adjustment (learning to cope reduces risk)
   474→  // 3. Bayesian belief updating (interventions update posterior risk)
   475→  
   476→  if (system.tippingPointRisk > 0.5) {
   477→    // Track when we first entered high-risk zone
   478→    if (!(system as any).firstHighRiskMonth) {
   479→      (system as any).firstHighRiskMonth = state.currentMonth;
   480→    }
   481→    
   482→    // === ELEMENT 1: TIME-DEPENDENT HAZARD BY BOUNDARY TYPE ===
   483→    // Fast killers (1-6 months): Water, food
   484→    const fastBoundaries = ['freshwater_change', 'biogeochemical_flows'];
   485→    const fastRisk = fastBoundaries.reduce((sum, name) => {
   486→      const boundary = system.boundaries[name as BoundaryName];
   487→      return sum + (boundary?.status !== 'safe' ? 1 : 0);
   488→    }, 0) / fastBoundaries.length;
   489→    
   490→    // Medium killers (6-36 months): Climate, ocean, pollution
   491→    const mediumBoundaries = ['climate_change', 'ocean_acidification', 'novel_entities'];
   492→    const mediumRisk = mediumBoundaries.reduce((sum, name) => {
   493→      const boundary = system.boundaries[name as BoundaryName];
   494→      return sum + (boundary?.status !== 'safe' ? 1 : 0);
   495→    }, 0) / mediumBoundaries.length;
   496→    
   497→    // Slow killers (36-120 months): Biodiversity, land use
   498→    const slowBoundaries = ['biosphere_integrity', 'land_system_change'];
   499→    const slowRisk = slowBoundaries.reduce((sum, name) => {
   500→      const boundary = system.boundaries[name as BoundaryName];
   501→      return sum + (boundary?.status !== 'safe' ? 1 : 0);
   502→    }, 0) / slowBoundaries.length;
   503→    
   504→    // Weighted by kill speed (fast = 3x, medium = 1x, slow = 0.3x)
   505→    const weightedRisk = (fastRisk * 3.0 + mediumRisk * 1.0 + slowRisk * 0.3) / 4.3;
   506→    
   507→    // === ELEMENT 2: SURVIVAL-BASED ADJUSTMENT (BAYESIAN INFERENCE) ===
   508→    // If we've survived high risk for N months, actual risk is probably lower than estimated
   509→    const monthsSurvivedAtHighRisk = state.currentMonth - ((system as any).firstHighRiskMonth || state.currentMonth);
   510→    // Decay: 30 years (360 months) to fully adjust belief
   511→    const survivalAdjustment = Math.max(0.3, 1.0 - (monthsSurvivedAtHighRisk / 360));
   512→    
   513→    // === ELEMENT 3: TRAJECTORY-BASED BELIEF UPDATE ===
   514→    // Are boundaries improving or worsening?
   515→    const recentImprovement = system.boundariesImproving / Math.max(1, system.boundariesBreached);
   516→    const trajectoryMultiplier = system.boundariesWorsening > system.boundariesImproving ? 1.3 : 0.7;
   517→    
   518→    // === COMBINED POSTERIOR RISK ===
   519→    const priorRisk = system.tippingPointRisk; // Original calculation
   520→    const posteriorRisk = weightedRisk * survivalAdjustment * trajectoryMultiplier;
   521→    const blendedRisk = (priorRisk + posteriorRisk) / 2; // Blend frequentist + Bayesian
   522→    
   523→    // Research-backed trigger rate: 40-70% over 30 years = 0.5-2% per year = 0.05-0.2% per month
   524→    const cascadeProbability = Math.pow(Math.max(0, blendedRisk - 0.5) / 0.5, 2.0);
   525→    const monthlyTriggerChance = cascadeProbability * 0.02; // Max 2% per month (not 10%)
   526→    
   527→    // Grace period: No trigger in first 24 months (cascades take 2-5 years to manifest)
   528→    const gracePeriod = state.currentMonth < 24;
   529→
   530→    // Stochastic trigger with Bayesian adjustment
   531→    if (!system.cascadeActive && !gracePeriod && Math.random() < monthlyTriggerChance) {
   532→      system.cascadeActive = true;
   533→      system.cascadeStartMonth = state.currentMonth;
   534→      console.log(`\n🌪️ ========== TIPPING POINT CASCADE TRIGGERED ==========`);
   535→      console.log(`Month: ${state.currentMonth}`);
   536→      console.log(`Boundaries breached: ${system.boundariesBreached}/9`);
   537→      console.log(`Prior risk: ${(priorRisk * 100).toFixed(1)}%`);
   538→      console.log(`Posterior risk (Bayesian): ${(posteriorRisk * 100).toFixed(1)}%`);
   539→      console.log(`Survival adjustment: ${(survivalAdjustment * 100).toFixed(0)}% (${monthsSurvivedAtHighRisk} months)`);
