  console.log(`    LOW:         ${(rootCause.confidenceDistribution.LOW * 1000).toFixed(1)}M (${formatPercent(rootCause.confidenceDistribution.LOW, totalDeaths)}%)`);
  console.log('==========================================\n');
}

