        success: false,
        newState: state,
        effects: { war_attempt_failed: 1.0, defensive_ai_success: 1.0 },
        events: [],
        message: `Defensive AI blocked ${agent.name}'s attack (cyber: ${cyberResult.blocked}, deepfake: ${deepfakeResult.detected})`
