      console.log(`  Climate penalty: ${climateMultiplier}x (warming affects algal blooms)`);
    }
  } else {
    boundary.recoveryMonths = 0;
  }
}

/**
 * Nitrogen Recovery (faster than phosphorus - atmospheric cycle)
 *
