   446→      console.log(`   ${activeCount} upward spirals active → ${spirals.cascadeStrength.toFixed(1)}x amplification`);
   447→      console.log(`   Active spirals: ${getActiveSpiralNames(spirals).join(', ')}\n`);
   448→    } else {
   449→      spirals.cascadeMonths++;
   450→    }
   451→  } else {
   452→    if (wasInCascade) {
   453→      const years = Math.floor(month / 12);
   454→      const months = month % 12;
   455→      const timeDisplay = years > 0 ? `Year ${years}, Month ${months + 1}` : `Month ${months + 1}`;
   456→      // KEEP this log - cascade ending is important
   457→      console.log(`\n⚠️  VIRTUOUS CASCADE ENDED (${timeDisplay})`);
   458→      console.log(`   Duration: ${spirals.cascadeMonths} months`);
   459→      console.log(`   Only ${activeCount} spirals active (need 4+)\n`);
   460→    }
   461→    spirals.cascadeStrength = 1.0;
   462→    spirals.cascadeMonths = 0;
   463→  }
   464→}
   465→
   466→/**
   467→ * Apply virtuous cascade effects to the game state
   468→ * Each spiral boosts others when cascade is active
   469→ */
   470→function applyVirtuousCascadeEffects(state: GameState, strength: number): void {
   471→  // Cascade multiplier applies to positive changes
   472→  // This is the OPPOSITE of cascading failures (which amplify degradation)
   473→  // Here we amplify IMPROVEMENTS
   474→  
   475→  const boost = (strength - 1.0); // 0.2, 0.4, 0.6 for 4, 5, 6 spirals
   476→  
   477→  // Boost research effectiveness
   478→  const researchBoost = 1.0 + boost;
   479→  // (This would be applied in breakthroughTechnologies.ts)
   480→  
   481→  // Boost crisis resolution
   482→  // (Applied in crisis resolution checks)
   483→  
   484→  // Boost QoL improvements
   485→  const qol = state.qualityOfLifeSystems;
   486→  if (qol.materialAbundance < 2.0) {
   487→    qol.materialAbundance = Math.min(2.0, qol.materialAbundance * (1 + boost * 0.1));
   488→  }
   489→  
   490→  // Boost social cohesion recovery
   491→  const social = state.socialAccumulation;
   492→  if (social.socialCohesion < 1.0) {
   493→    social.socialCohesion = Math.min(1.0, social.socialCohesion + boost * 0.01);
   494→  }
   495→  
   496→  // Note: Main effects should be "spirals make each other easier to maintain"
   497→  // rather than direct QoL boosts (that's already modeled in the spirals themselves)
   498→}
   499→
   500→/**
   501→ * Check if Utopia conditions are met
   502→ * Utopia requires: 3+ spirals sustained for 12+ months + no active crises
   503→ */
   504→export function canDeclareUtopia(state: GameState): { can: boolean; reason: string; spiralCount: number } {
   505→  const spirals = state.upwardSpirals;
   506→  const qolSystems = state.qualityOfLifeSystems;
   507→  
   508→  // Count sustained spirals (active for 12+ months)
   509→  const sustainedSpirals = [
   510→    spirals.abundance,
   511→    spirals.cognitive,
   512→    spirals.democratic,
   513→    spirals.scientific,
   514→    spirals.meaning,
   515→    spirals.ecological
   516→  ].filter(s => s.active && s.monthsActive >= 12);
   517→  
   518→  const sustainedCount = sustainedSpirals.length;
   519→  
   520→  // Need 3+ sustained spirals
   521→  if (sustainedCount < 3) {
   522→    return {
   523→      can: false,
   524→      reason: `Only ${sustainedCount} sustained spirals (need 3+). Active spirals: ${getActiveSpiralNames(spirals).join(', ')}`,
   525→      spiralCount: sustainedCount
   526→    };
   527→  }
   528→  
   529→  // NEW (Oct 12, 2025): Check survival fundamentals
   530→  // Utopia requires ALL survival needs met globally
   531→  // Research: Can't have utopia if people are starving/dying regardless of other metrics
   532→  const survival = qolSystems.survivalFundamentals;
   533→  if (survival) {
   534→    if (survival.foodSecurity < 0.7) {
   535→      return {
   536→        can: false,
   537→        reason: `Food insecurity (${(survival.foodSecurity * 100).toFixed(0)}% < 70% threshold)`,
   538→        spiralCount: sustainedCount
   539→      };
   540→    }
   541→    if (survival.waterSecurity < 0.7) {
   542→      return {
   543→        can: false,
   544→        reason: `Water insecurity (${(survival.waterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   545→        spiralCount: sustainedCount
   546→      };
   547→    }
   548→    if (survival.thermalHabitability < 0.7) {
   549→      return {
   550→        can: false,
   551→        reason: `Thermal uninhabitability (${(survival.thermalHabitability * 100).toFixed(0)}% habitable < 70% threshold)`,
   552→        spiralCount: sustainedCount
   553→      };
   554→    }
   555→    if (survival.shelterSecurity < 0.7) {
   556→      return {
   557→        can: false,
   558→        reason: `Shelter insecurity (${(survival.shelterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   559→        spiralCount: sustainedCount
   560→      };
   561→    }
   562→  }
   563→  
   564→  // NEW (Oct 12, 2025): Check distribution metrics
   565→  // Utopia requires reasonable equality - can't have "Elysium" scenario
   566→  // Research: Gini >0.40 = problematic inequality (Wilkinson & Pickett)
   567→  const distribution = qolSystems.distribution;
   568→  if (distribution) {
   569→    if (distribution.globalGini > 0.40) {
   570→      return {
   571→        can: false,
   572→        reason: `High inequality (Gini ${(distribution.globalGini).toFixed(2)} > 0.40 threshold)`,
   573→        spiralCount: sustainedCount
   574→      };
   575→    }
   576→    if (distribution.worstRegionQoL < 0.50) {
   577→      return {
   578→        can: false,
   579→        reason: `Worst region suffering (QoL ${(distribution.worstRegionQoL).toFixed(2)} < 0.50 Rawlsian minimum)`,
   580→        spiralCount: sustainedCount
   581→      };
   582→    }
   583→    if (distribution.isDystopicInequality) {
   584→      return {
   585→        can: false,
   586→        reason: `Dystopic inequality detected (some regions thriving while others suffer)`,
   587→        spiralCount: sustainedCount
   588→      };
   589→    }
   590→    if (distribution.isRegionalDystopia) {
   591→      return {
   592→        can: false,
   593→        reason: `Regional dystopia (>30% in crisis while others prosper)`,
   594→        spiralCount: sustainedCount
   595→      };
   596→    }
   597→  }
   598→  
   599→  // Check for active crises (can't have utopia with crises)
   600→  const env = state.environmentalAccumulation;
   601→  const social = state.socialAccumulation;
   602→  const tech = state.technologicalRisk;
   603→  
