   621→      spiralCount: sustainedCount
   622→    };
   623→  }
   624→  
   625→  // Success! All conditions met
   626→  return {
   627→    can: true,
   628→    reason: `${sustainedCount} upward spirals sustained for 12+ months: ${getSustainedSpiralNames(spirals).join(', ')}`,
