function updateClimateRecovery(state: GameState, rng: RNGFunction): void {
  const boundary = state.planetaryBoundariesSystem?.boundaries.climate_change;
  if (!boundary) return;

  const globalWarming = state.climateState?.globalWarming ?? 1.2;
  const annualEmissions = state.climateState?.annualEmissions ?? 40; // GtCO₂
  const annualCDR = state.climateState?.annualCDR ?? 0; // GtCO₂

  const netEmissions = annualEmissions - annualCDR;

  // Recovery requires: temperature < 1.5°C AND net-negative emissions
  const tempBelowThreshold = globalWarming < 1.5;
  const netNegative = netEmissions < 0;

  const isRecovering = tempBelowThreshold && netNegative;

  // Climate feedback acceleration (research-skeptic requirement)
  // Changed from 2.0°C → 1.5°C based on 2024-2025 real-world data
  const climateMultiplier = globalWarming >= 1.5 ? 1.5 : 1.0;

  // Governance capacity (international cooperation critical for climate)
  const internationalCooperation = state.government?.internationalCooperation ?? 0.5;
  const governanceMultiplier = internationalCooperation < 0.5 ? 0.5 : 1.0;

  if (isRecovering) {
    const combinedMultiplier = governanceMultiplier / climateMultiplier;
    boundary.recoveryMonths = (boundary.recoveryMonths ?? 0) + combinedMultiplier;

    // FIX (Oct 21, 2025): ACTUALLY IMPROVE ENVIRONMENTAL STATE
    // Climate stability improvement: 0.1-0.5% monthly
    // Research: IPCC AR6 overshoot scenarios show VERY slow natural recovery
    // Even with net-negative emissions, temperature stabilization takes decades
    const baseRecoveryRate = 0.001; // 0.1%/month (conservative)
    const governanceBonus = governanceMultiplier > 0.7 ? 0.002 : 0; // +0.2% if strong governance
    const climatePenalty = climateMultiplier > 1 ? 0.5 : 1.0; // Half speed if warming ≥ 1.5°C

    const recoveryRate = (baseRecoveryRate + governanceBonus) * climatePenalty;

    // CRITICAL: Actually improve climate stability
    if (state.environmentalAccumulation) {
      const env = state.environmentalAccumulation;
      env.climateStability = Math.min(1.0, env.climateStability + recoveryRate);

      // Log every 2 years if recovering
      if (state.currentMonth % 24 === 0 && recoveryRate > 0) {
        console.log(`🌡️  CLIMATE RECOVERY: Stability improving at +${(recoveryRate * 100).toFixed(3)}%/month`);
        console.log(`   Current stability: ${(env.climateStability * 100).toFixed(1)}%`);
      }
    }

    // Base recovery: 24 months, adjusted for climate feedbacks and governance
    const recoveryThreshold = 24 * climateMultiplier / governanceMultiplier;

    if ((boundary.recoveryMonths ?? 0) >= recoveryThreshold) {
      boundary.status = 'safe';
      boundary.trend = 'improving';
      boundary.monthsBreached = 0;
      boundary.breachYear = null;

      console.log(`\n=== Climate Boundary RECOVERED ===`);
      console.log(`  Temperature: ${globalWarming.toFixed(2)}°C (below 1.5°C threshold)`);
      console.log(`  Net emissions: ${netEmissions.toFixed(1)} GtCO₂/year (negative)`);
      console.log(`  Recovery time: ${Math.floor((boundary.recoveryMonths ?? 0) / 12)} years`);
      console.log(`  Climate feedback penalty: ${climateMultiplier}x (warming ≥ 1.5°C)`);
    }
  } else {
    boundary.recoveryMonths = 0;
  }
}

