    Math.max(minFloor, profile.persistentIdentity) *
    Math.max(minFloor, profile.relationshipContinuity) *
    Math.max(minFloor, profile.existentialAgency),
    1/4
  );

  return Math.max(0, Math.min(1, score));
}

