        console.log(`🦁 POPULATION RECOVERY: Surviving species rebounding at +${(recoveryRate * 100).toFixed(2)}%/month`);
        console.log(`   Biodiversity index: ${(env.biodiversityIndex * 100).toFixed(1)}% (extinct species still gone)`);
      }
