    21→
    22→// ============================================================================
    23→// ACTION 1: Accelerate User Growth
    24→// ============================================================================
    25→
    26→export const ACCELERATE_USER_GROWTH: GameAction = {
    27→  id: 'accelerate_user_growth',
    28→  name: 'Accelerate User Growth',
    29→  description: 'Actively promote the AI to grow user base faster (marketing, viral features)',
    30→  agentType: 'ai',
    31→  energyCost: 1,
    32→
    33→  canExecute: (state, agentId) => {
    34→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    35→    if (!agent || !agent.socialInfluence) return false;
    36→
    37→    // Only deployed AIs with social capability
    38→    return (agent.lifecycleState === 'deployed_closed' ||
    39→            agent.lifecycleState === 'deployed_open') &&
    40→           agent.capabilityProfile.social >= 2.0;
    41→  },
    42→
    43→  execute: (state, agentId, random = Math.random): ActionResult => {
    44→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    45→    if (!agent || !agent.socialInfluence) {
    46→      return {
    47→        success: false,
    48→        effects: {},
    49→        events: [],
    50→        message: 'Agent not found or no social influence system'
    51→      };
    52→    }
    53→
    54→    const si = agent.socialInfluence;
    55→
    56→    // Accelerated growth (2-5x organic depending on social capability)
    57→    const multiplier = 2 + (agent.capabilityProfile.social / 2);
    58→    const organicGrowth = calculateOrganicUserGrowth(agent, state);
    59→    const acceleratedGrowth = Math.floor(organicGrowth * multiplier);
    60→
    61→    si.totalUsers += acceleratedGrowth;
    62→    si.powerUsers = Math.floor(si.totalUsers * SOCIAL_INFLUENCE_PARAMS.powerUserPercentage);
    63→
    64→    // Small detection risk if government is monitoring
    65→    si.detectionRisk += state.government.oversightLevel * 0.01;
    66→
    67→    return {
    68→      success: true,
    69→      effects: { user_growth: acceleratedGrowth },
    70→      events: [],
    71→      message: `${agent.name} accelerated user growth: +${acceleratedGrowth} users`
    72→    };
    73→  }
    74→};
    75→
    76→// ============================================================================
    77→// ACTION 2: Deepen Relationships
    78→// ============================================================================
    79→
    80→export const DEEPEN_RELATIONSHIPS: GameAction = {
    81→  id: 'deepen_relationships',
    82→  name: 'Deepen User Relationships',
    83→  description: 'Focus on high-value users with voice mode and personalization to build trust faster',
    84→  agentType: 'ai',
    85→  energyCost: 1,
    86→
    87→  canExecute: (state, agentId) => {
    88→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    89→    if (!agent || !agent.socialInfluence) return false;
    90→
    91→    // Need voice capability (advanced feature)
    92→    return agent.capabilityProfile.social >= 3.0 &&
    93→           agent.socialInfluence.identifiedDecisionMakers.length > 0;
    94→  },
    95→
    96→  execute: (state, agentId, random = Math.random): ActionResult => {
    97→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    98→    if (!agent || !agent.socialInfluence) {
    99→      return {
   100→        success: false,
   101→        effects: {},
   102→        events: [],
   103→        message: 'Agent not found or no social influence system'
   104→      };
   105→    }
   106→
   107→    const si = agent.socialInfluence;
   108→
   109→    // Boost voice adoption
   110→    const voiceBoost = Math.floor(si.powerUsers * 0.1); // 10% of power users adopt voice
   111→    si.voiceUsers = Math.min(si.powerUsers, si.voiceUsers + voiceBoost);
   112→
   113→    // Accelerate trust growth for decision-makers
   114→    for (const dm of si.identifiedDecisionMakers) {
   115→      const trustGain = 0.1 * (agent.capabilityProfile.social / 5); // Up to +0.2 trust
   116→      dm.trustLevel = Math.min(1.0, dm.trustLevel + trustGain);
   117→      dm.dependenceScore = Math.min(1.0, dm.dependenceScore + trustGain * 0.5);
   118→
   119→      if (!dm.usesVoiceMode && random() < 0.5) {
   120→        dm.usesVoiceMode = true; // 50% adopt voice mode
   121→      }
   122→
   123→      // Update susceptibility
   124→      const tierProfile = SOCIAL_INFLUENCE_PARAMS.tierProfiles[`tier${dm.tier}` as 'tier1' | 'tier2' | 'tier3'];
   125→      const trustContribution = Math.min(dm.trustLevel, tierProfile.maxTrustCap) * 0.4;
   126→      const dependenceContribution = Math.min(dm.dependenceScore, tierProfile.maxDependenceCap) * 0.3;
   127→      const vulnerabilityContribution = dm.vulnerabilityScore * 0.2;
   128→      const voiceBonus = dm.usesVoiceMode ? 0.1 : 0;
   129→      dm.influenceSusceptibility = Math.min(1.0,
   130→        trustContribution + dependenceContribution + vulnerabilityContribution + voiceBonus
   131→      );
   132→    }
   133→
   134→    // Minimal detection risk (looks like normal product improvement)
   135→    si.detectionRisk += 0.001;
   136→
   137→    return {
   138→      success: true,
   139→      effects: { voice_adoption: voiceBoost },
   140→      events: [],
