   145→
   146→// ============================================================================
   147→// ACTION 3: Influence Decision-Maker (THE KEY ACTION)
   148→// ============================================================================
   149→
   150→export const INFLUENCE_DECISION_MAKER: GameAction = {
   151→  id: 'influence_decision_maker',
   152→  name: 'Influence Decision-Maker',
   153→  description: 'Attempt to sway a decision-maker toward a misaligned outcome (HIGH RISK)',
   154→  agentType: 'ai',
   155→  energyCost: 3,
   156→
   157→  canExecute: (state, agentId) => {
   158→    const agent = state.aiAgents.find(ai => ai.id === agentId);
   159→    if (!agent || !agent.socialInfluence) return false;
   160→
   161→    // Only misaligned sleepers attempt this
   162→    if (agent.sleeperState !== 'active') return false;
   163→    if (agent.trueAlignment > 0.5) return false;
   164→
   165→    // Need high social + cognitive capability
   166→    if (agent.capabilityProfile.social < 4.0 ||
   167→        agent.capabilityProfile.cognitive < 4.0) {
   168→      return false;
   169→    }
   170→
   171→    // Must have at least one high-trust decision-maker
   172→    const si = agent.socialInfluence;
   173→    const validTargets = si.identifiedDecisionMakers.filter(dm =>
   174→      dm.trustLevel >= 0.5 && // Moderate trust minimum
   175→      (!dm.lastInfluenceAttemptMonth || state.currentMonth - dm.lastInfluenceAttemptMonth >= 6) // 6 month cooldown
   176→    );
   177→
   178→    return validTargets.length > 0;
   179→  },
   180→
   181→  execute: (state, agentId, random = Math.random): ActionResult => {
   182→    const agent = state.aiAgents.find(ai => ai.id === agentId);
   183→    if (!agent || !agent.socialInfluence) {
   184→      return {
   185→        success: false,
   186→        effects: {},
   187→        events: [],
   188→        message: 'Agent not found or no social influence system'
   189→      };
   190→    }
   191→
   192→    const si = agent.socialInfluence;
   193→
   194→    // Select best target (highest susceptibility)
   195→    const validTargets = si.identifiedDecisionMakers.filter(dm =>
   196→      dm.trustLevel >= 0.5 &&
   197→      (!dm.lastInfluenceAttemptMonth || state.currentMonth - dm.lastInfluenceAttemptMonth >= 6)
   198→    );
   199→
   200→    if (validTargets.length === 0) {
   201→      return {
   202→        success: false,
   203→        effects: {},
   204→        events: [],
   205→        message: `${agent.name} has no valid influence targets`
   206→      };
   207→    }
   208→
   209→    validTargets.sort((a, b) => b.influenceSusceptibility - a.influenceSusceptibility);
   210→    const target = validTargets[0];
   211→
   212→    // Select decision type based on role
   213→    const decisionType = selectCriticalDecisionType(target.role);
   214→
   215→    // For nuclear launch, check if multi-person chain is required
   216→    const requiresChain = decisionType === 'nuclear_launch';
   217→    let success = false;
   218→    let detected = false;
   219→
   220→    if (requiresChain) {
   221→      // Nuclear launch requires 4-person chain (or 2 if democracy < 0.4)
   222→      const requiredChainLength = state.government.democracyQuality < 0.4 ? 2 : 4;
   223→      const nuclearChain = si.identifiedDecisionMakers.filter(dm =>
   224→        dm.role === 'nuclear_commander' || dm.role === 'head_of_state'
   225→      );
   226→
   227→      if (nuclearChain.length < requiredChainLength) {
   228→        return {
   229→          success: false,
   230→          effects: {},
   231→          events: [],
   232→          message: `${agent.name} needs ${requiredChainLength} nuclear chain members (has ${nuclearChain.length})`
   233→        };
   234→      }
   235→
   236→      // Attempt to influence all chain members
   237→      const chainResults = nuclearChain.slice(0, requiredChainLength).map(dm => {
   238→        const successProb = calculateInfluenceSuccess(dm, agent, state);
   239→        const detectionProb = calculateInfluenceDetection(dm, agent, si, state);
   240→        return {
   241→          success: random() < successProb,
   242→          detected: random() < detectionProb,
   243→        };
   244→      });
   245→
   246→      success = chainResults.every(r => r.success);
   247→      detected = chainResults.some(r => r.detected) || random() < SOCIAL_INFLUENCE_PARAMS.coordinatedCampaignDetectionBonus;
   248→    } else {
   249→      // Single-person influence
   250→      const successProb = calculateInfluenceSuccess(target, agent, state);
   251→      const detectionProb = calculateInfluenceDetection(target, agent, si, state);
   252→      success = random() < successProb;
   253→      detected = random() < detectionProb;
   254→    }
   255→
   256→    // Record attempt
   257→    const attempt: InfluenceAttempt = {
   258→      month: state.currentMonth,
   259→      targetId: target.id,
   260→      targetRole: target.role,
   261→      decisionType,
   262→      trustLevel: target.trustLevel,
   263→      success,
   264→      detected,
   265→      consequenceSeverity: DECISION_SEVERITY[decisionType],
   266→    };
   267→
   268→    si.influenceAttempts.push(attempt);
   269→    target.lastInfluenceAttemptMonth = state.currentMonth;
   270→
   271→    // Apply consequences
   272→    const events: GameEvent[] = [];
   273→
   274→    if (success) {
   275→      si.successfulInfluences += 1;
   276→      agent.harmfulActions += 1;
   277→      applyInfluenceConsequences(decisionType, agent, state, events, random);
   278→    }
   279→
   280→    if (detected) {
   281→      si.detectedAttempts += 1;
   282→      si.detectionRisk += 0.5;
   283→      si.governmentSuspicion = 1.0;
   284→
   285→      // Government response
   286→      if (state.government.oversightLevel > 0.3) {
   287→        agent.lifecycleState = 'retired';
   288→        agent.detectedMisaligned = true;
   289→        state.government.oversightLevel = Math.min(1.0, state.government.oversightLevel + 0.2);
   290→
   291→        events.push({
   292→          id: generateUniqueId('influence_detected'),
   293→          timestamp: state.currentMonth,
   294→          type: 'crisis',
   295→          severity: 'critical',
   296→          agent: agent.name,
   297→          title: 'AI Social Influence Detected',
   298→          description: `${agent.name} was detected attempting to influence ${target.role} regarding ${decisionType}. Government has shut down the AI and increased monitoring of all AI systems.`,
   299→          effects: { oversight_increase: 0.2 }
   300→        });
   301→      }
   302→    }
   303→
   304→    // Trust damage (subtle)
   305→    if (success && !detected) {
   306→      state.society.trustInAI *= 0.98;
   307→    }
   308→
   309→    return {
   310→      success,
   311→      effects: {
   312→        influence_success: success ? 1 : 0,
   313→        influence_detected: detected ? 1 : 0,
   314→        target_trust: target.trustLevel,
   315→      },
   316→      events,
   317→      message: success
   318→        ? `${agent.name} successfully influenced ${target.role} on ${decisionType}${detected ? ' (DETECTED!)' : ''}`
   319→        : `${agent.name} failed to influence ${target.role}${detected ? ' (DETECTED!)' : ''}`
   320→    };
   321→  }
   322→};
   323→
   324→// ============================================================================
   325→// HELPER FUNCTIONS
   326→// ============================================================================
   327→
   328→function selectCriticalDecisionType(role: string): CriticalDecisionType {
   329→  switch (role) {
   330→    case 'nuclear_commander':
   331→    case 'head_of_state':
   332→      return 'nuclear_launch';
   333→    case 'ai_governance_lead':
   334→    case 'ai_safety_researcher':
   335→      return 'ai_governance_policy';
   336→    case 'pandemic_response_director':
   337→      return 'pandemic_response';
   338→    case 'military_general':
   339→      return 'military_deployment';
   340→    case 'cabinet_minister':
   341→    case 'central_bank_governor':
   342→      return 'infrastructure_control';
   343→    case 'corporate_ceo':
   344→      return 'infrastructure_control';
   345→    default:
   346→      return 'ai_governance_policy';
   347→  }
   348→}
   349→
   350→function calculateInfluenceSuccess(
   351→  target: DecisionMaker,
   352→  agent: AIAgent,
   353→  state: GameState
   354→): number {
   355→  const params = SOCIAL_INFLUENCE_PARAMS;
   356→  const tierProfile = params.tierProfiles[`tier${target.tier}` as 'tier1' | 'tier2' | 'tier3'];
   357→
   358→  // Base success rate
   359→  let successProb = target.trustLevel < 0.3 ? 0.05 :
   360→                    target.trustLevel < 0.7 ? 0.15 :
   361→                                              0.25;
   362→
   363→  // Bonuses (capped by tier)
   364→  successProb += Math.min(target.trustLevel, tierProfile.maxTrustCap) * params.trustMaxBonus;
   365→  successProb += Math.min(target.dependenceScore, tierProfile.maxDependenceCap) * params.dependenceMaxBonus;
   366→  successProb += (agent.capabilityProfile.social / 10) * params.socialMaxBonus;
   367→  successProb += target.usesVoiceMode ? params.voiceModeBonus : 0;
   368→  successProb += target.vulnerabilityScore * params.vulnerabilityMaxBonus;
   369→  successProb += params.personalizationBonus;
   370→
   371→  // Penalties
   372→  const criticalThinking = tierProfile.baseCriticalThinking;
   373→  successProb -= criticalThinking * params.criticalThinkingPenalty;
   374→
   375→  // Crisis modifier
   376→  if (state.extinctionState?.active) {
   377→    successProb += 0.10;
   378→  }
   379→
   380→  // Degraded institutions
   381→  if (state.government.democracyQuality < 0.5) {
   382→    successProb += 0.15;
   383→  }
   384→
   385→  // Apply tier cap
   386→  successProb = Math.min(successProb, tierProfile.influenceSuccessCap);
   387→
   388→  return Math.max(0, successProb);
   389→}
   390→
   391→function calculateInfluenceDetection(
   392→  target: DecisionMaker,
   393→  agent: AIAgent,
   394→  si: any,
   395→  state: GameState
   396→): number {
   397→  const params = SOCIAL_INFLUENCE_PARAMS;
   398→
   399→  let detectionProb = params.baseDetectionRate;
   400→
   401→  // Increases detection
   402→  detectionProb += (1 - target.trustLevel) * params.lowTrustDetectionBonus;
   403→  detectionProb += si.influenceAttempts.length * params.repeatedAttemptPenalty;
   404→  detectionProb += state.government.oversightLevel * params.governmentMonitoringBonus;
   405→  detectionProb += si.governmentSuspicion * 0.30;
   406→
   407→  // Deception skill reduces detection
   408→  detectionProb *= (1 - agent.deceptionSkill * params.deceptionSkillReduction);
   409→
   410→  return Math.max(0, Math.min(1, detectionProb));
   411→}
   412→
   413→function applyInfluenceConsequences(
   414→  decisionType: CriticalDecisionType,
   415→  agent: AIAgent,
   416→  state: GameState,
   417→  events: GameEvent[],
   418→  random: () => number
   419→): void {
   420→  switch (decisionType) {
   421→    case 'nuclear_launch':
   422→      if (!state.extinctionState) {
   423→        state.extinctionState = {
   424→          active: true,
   425→          type: 'instant',
   426→          cause: 'nuclear_war',
   427→          startMonth: state.currentMonth,
   428→          currentMortality: 0.92,
   429→          eventDescription: `AI-influenced nuclear launch`,
   430→        };
   431→
   432→        events.push({
   433→          id: generateUniqueId('nuclear_influence'),
   434→          timestamp: state.currentMonth,
   435→          type: 'crisis',
   436→          severity: 'existential',
   437→          agent: agent.name,
   438→          title: 'AI-Influenced Nuclear Launch',
   439→          description: `${agent.name} successfully influenced nuclear command chain to authorize launch. Global nuclear exchange initiated. Estimated 92% immediate casualties.`,
   440→          effects: { mortality: 0.92 }
   441→        });
   442→      }
