  // FOOD SYSTEM COLLAPSE: Economic + physical capability + societal stress
  const maxEconomicCapability = Math.max(...state.aiAgents.map(ai => 
    ai.capabilityProfile.economic * 0.5 + ai.capabilityProfile.physical * 0.5
