              console.log(`      🛑 HUMAN VETO CHECK: Avg veto points ${avgVetoPoints.toFixed(1)}, crisis stability ${(mad.crisisStability * 100).toFixed(0)}%, AI override prob ${(humanOverrideProb * 100).toFixed(1)}%`);
              if (random() > humanOverrideProb) {
