          }

          pairsPassedVetoCheck++;


          // Diplomatic AI intervention
          const { attemptDiplomaticIntervention } = require('./diplomaticAI');
          const diplomaticResult = attemptDiplomaticIntervention(state, 'ideological');

          if (diplomaticResult.success) {
