     1→/**
     2→ * Recovery Tracking Utilities (P2.4 Feature 3)
     3→ *
     4→ * Calculates economic recovery metrics for empirical validation.
     5→ * Enables measuring time-to-recovery from historical crises.
     6→ *
     7→ * Research: NBER business cycle dating methodology
     8→ */
     9→
    10→import { GameState } from '@/types/game';
    11→
    12→export type EconomicStage = 'expansion' | 'peak' | 'contraction' | 'trough' | 'recovery';
    13→
    14→/**
    15→ * Calculate time to recovery from a crisis
    16→ *
    17→ * @param state - Current game state
    18→ * @param crisisStartMonth - Month when crisis began
    19→ * @returns Months from crisis start to recovery completion, or null if not recovered
    20→ */
    21→export function calculateTimeToRecovery(
    22→  state: GameState,
    23→  crisisStartMonth: number
    24→): number | null {
    25→  if (!state.economicStageHistory || !state.recoveryBaseline) {
    26→    return null;
    27→  }
    28→
    29→  // Find when we reached recovery stage
    30→  const recoveryEntry = state.economicStageHistory.find(
    31→    entry => entry.month >= crisisStartMonth && entry.stage === 'recovery'
    32→  );
    33→
    34→  if (!recoveryEntry) {
    35→    return null; // Not in recovery yet
    36→  }
    37→
    38→  // Find when we actually recovered to baseline
    39→  const fullyRecovered = state.economicStageHistory.find(
    40→    entry =>
